mapper.update:
UPDATE PEACH_SCHEDULER_EXECUTION
SET STATE = #{toState}, FINISH_TIME = #{finishTime}, DURATION_MS = #{durationMs}, LEASE_UNTIL = NULL,
    NEXT_RETRY_TIME = NULL, ERROR_TYPE = #{errorType}, ERROR_MESSAGE = #{errorMessage},
    VERSION = VERSION + 1, MODIFY_TIME = NOW(3)
WHERE EXECUTION_ID = #{executionId} AND STATE = #{fromState} AND VERSION = #{version}
  AND EXECUTOR_INSTANCE = #{executorInstance}

mapper.select:
SELECT  FROM PEACH_SCHEDULER_EXECUTION
WHERE STATE = 'CREATED'
ORDER BY CREATED_TIME ASC LIMIT #{limit}

SELECT  FROM PEACH_SCHEDULER_EXECUTION
WHERE STATE = 'RUNNING' AND LEASE_UNTIL < #{now}
ORDER BY LEASE_UNTIL ASC LIMIT #{limit}

SELECT  FROM PEACH_SCHEDULER_EXECUTION
WHERE STATE = 'RETRY_WAIT' AND NEXT_RETRY_TIME <= #{now}
ORDER BY NEXT_RETRY_TIME ASC LIMIT #{limit}

SELECT  FROM PEACH_SCHEDULER_EXECUTION
WHERE 1 = 1
AND JOB_CODE = #{jobCode}
AND STATE = #{state}
ORDER BY CREATED_TIME DESC
LIMIT #{safePageSize} OFFSET #{offset}
